# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 255" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="255" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">TEK BASAMAKLI TEPKİMEDE HIZ BAĞINTISI, DERECE VE MOLEKÜLERİTE</text>\n  <rect x="20" y="42" width="660" height="46" rx="8" fill="#ede9fe" stroke="#7c3aed" stroke-width="2"/>\n  <text x="350" y="62" text-anchor="middle" font-size="13" font-weight="bold" fill="#5b21b6">Tek Basamaklı Tepkime:   Zn(k)  +  2HCl(suda)  +  O2(g)   →   ZnCl2(suda)  +  H2O(s)</text>\n  <text x="350" y="80" text-anchor="middle" font-size="10.5" fill="#334155">Not: Gazlar (g) ve sulu çözeltiler (suda) hız bağıntısına yazılır; saf katı (k) ve saf sıvılar (s) yazılmaz.</text>\n\n  <rect x="20" y="102" width="210" height="136" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="125" y="124" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">1. Hız Bağıntısı (Denklemi)</text>\n  <rect x="35" y="136" width="180" height="34" rx="6" fill="#ffffff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="125" y="158" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">r = k · [HCl]² · [O2]</text>\n  <text x="32" y="190" font-size="10" fill="#334155">• Zn(k) katı olduğundan yer almaz.</text>\n  <text x="32" y="208" font-size="10" fill="#334155">• HCl\'nin katsayısı 2 üs olarak gelir.</text>\n  <text x="32" y="226" font-size="10" fill="#334155">• O2 gazının katsayısı 1 üs olur.</text>\n\n  <rect x="245" y="102" width="210" height="136" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="350" y="124" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">2. Tepkime Derecesi (Mertebe)</text>\n  <rect x="260" y="136" width="180" height="34" rx="6" fill="#ffffff" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="350" y="158" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#b45309">Derece = 2 + 1 = 3</text>\n  <text x="257" y="190" font-size="10" fill="#334155">• Deneysel hız denkleminden bulunur.</text>\n  <text x="257" y="208" font-size="10" fill="#334155">• HCl\'ye göre 2., O2\'ye göre 1. derece.</text>\n  <text x="257" y="226" font-size="10" fill="#334155">• Sıfır veya kesirli sayı da olabilir.</text>\n\n  <rect x="470" y="102" width="210" height="136" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="575" y="124" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">3. Molekülerite (Tanecik Sayısı)</text>\n  <rect x="485" y="136" width="180" height="34" rx="6" fill="#ffffff" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="575" y="158" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">Molekülerite = 1 + 2 + 1 = 4</text>\n  <text x="482" y="190" font-size="10" fill="#334155">• Net tepkime girenlerinden bulunur.</text>\n  <text x="482" y="208" font-size="10" fill="#334155">• Katı, sıvı, gaz tüm girenler toplanır.</text>\n  <text x="482" y="226" font-size="10" fill="#334155">• Daima pozitif tam sayıdır (Teorik).</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">MEKANİZMALI TEPKİMEDE YAVAŞ BASAMAK, ARA ÜRÜN VE KATALİZÖR</text>\n  <rect x="20" y="44" width="380" height="198" rx="10" fill="#ffffff" stroke="#2563eb" stroke-width="2"/>\n  <text x="210" y="66" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">Tepkime Mekanizması ve Taraf Tarafa Toplama</text>\n  <rect x="34" y="78" width="352" height="36" rx="6" fill="#fee2e2" stroke="#dc2626" stroke-width="1.5"/>\n  <text x="44" y="94" font-size="10.5" font-weight="bold" fill="#991b1b">1. Basamak (Yavaş - Hız Belirleyen):</text>\n  <text x="44" y="109" font-size="11" font-weight="bold" fill="#0f172a">H2O2(suda) + I⁻(suda)  →  H2O(s) + IO⁻(suda)</text>\n\n  <rect x="34" y="122" width="352" height="36" rx="6" fill="#e0f2fe" stroke="#0284c7" stroke-width="1.5"/>\n  <text x="44" y="138" font-size="10.5" font-weight="bold" fill="#0369a1">2. Basamak (Hızlı):</text>\n  <text x="44" y="153" font-size="11" font-weight="bold" fill="#0f172a">H2O2(suda) + IO⁻(suda)  →  H2O(s) + O2(g) + I⁻(suda)</text>\n\n  <line x1="34" y1="168" x2="386" y2="168" stroke="#334155" stroke-width="2"/>\n  <rect x="34" y="176" width="352" height="54" rx="6" fill="#dcfce7" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="44" y="194" font-size="10.5" font-weight="bold" fill="#15803d">Net (Toplam) Tepkime Denklemi:</text>\n  <text x="44" y="211" font-size="11.5" font-weight="bold" fill="#0f172a">2H2O2(suda)  →  2H2O(s) + O2(g)</text>\n  <text x="44" y="225" font-size="9.5" fill="#334155">(Molekülerite = 2, ancak tepkime tek basamaklı değildir!)</text>\n\n  <rect x="415" y="44" width="265" height="60" rx="8" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="547" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#991b1b">Hız Bağıntısı (Yavaş Basamaktan)</text>\n  <text x="547" y="83" text-anchor="middle" font-size="12" font-weight="bold" fill="#0f172a">r = k · [H2O2] · [I⁻]</text>\n  <text x="547" y="98" text-anchor="middle" font-size="10" fill="#334155">Tepkime Derecesi = 1 + 1 = 2</text>\n\n  <rect x="415" y="113" width="265" height="60" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="547" y="133" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">Ara Ürün: IO⁻(suda)</text>\n  <text x="547" y="151" text-anchor="middle" font-size="10" fill="#334155">1. basamakta ürün olarak oluşur,</text>\n  <text x="547" y="165" text-anchor="middle" font-size="10" fill="#334155">2. basamakta reaktif olarak harcanır.</text>\n\n  <rect x="415" y="182" width="265" height="60" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="547" y="202" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">Katalizör: I⁻(suda)</text>\n  <text x="547" y="220" text-anchor="middle" font-size="10" fill="#334155">1. basamağa reaktif olarak girer,</text>\n  <text x="547" y="234" text-anchor="middle" font-size="10" fill="#334155">2. basamaktan değişmeden geri çıkar.</text>\n</svg>', '<svg viewBox="0 0 700 255" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="255" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">DENEYSEL HIZ TABLOSU ÇÖZÜMÜ VE HIZ SABİTİ (k) ÖZELLİKLERİ</text>\n  <rect x="20" y="44" width="335" height="194" rx="10" fill="#ffffff" stroke="#2563eb" stroke-width="2"/>\n  <rect x="20" y="44" width="335" height="28" rx="8" fill="#2563eb"/>\n  <text x="55" y="63" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#ffffff">Deney</text>\n  <text x="125" y="63" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#ffffff">[X] (mol/L)</text>\n  <text x="200" y="63" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#ffffff">[Y] (mol/L)</text>\n  <text x="292" y="63" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#ffffff">Hız r (mol/L·s)</text>\n\n  <text x="55" y="92" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e293b">1</text>\n  <text x="125" y="92" text-anchor="middle" font-size="11" fill="#1e293b">0,10</text>\n  <text x="200" y="92" text-anchor="middle" font-size="11" fill="#1e293b">0,10</text>\n  <text x="292" y="92" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">2,0 · 10⁻³</text>\n  <line x1="28" y1="102" x2="345" y2="102" stroke="#cbd5e1" stroke-width="1"/>\n\n  <text x="55" y="122" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e293b">2</text>\n  <text x="125" y="122" text-anchor="middle" font-size="11" fill="#1e293b">0,10</text>\n  <text x="200" y="122" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">0,20 (×2)</text>\n  <text x="292" y="122" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">4,0 · 10⁻³ (×2)</text>\n  <line x1="28" y1="132" x2="345" y2="132" stroke="#cbd5e1" stroke-width="1"/>\n\n  <text x="55" y="152" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e293b">3</text>\n  <text x="125" y="152" text-anchor="middle" font-size="11" font-weight="bold" fill="#b91c1c">0,30 (×3)</text>\n  <text x="200" y="152" text-anchor="middle" font-size="11" fill="#1e293b">0,10</text>\n  <text x="292" y="152" text-anchor="middle" font-size="11" font-weight="bold" fill="#b91c1c">1,8 · 10⁻² (×9)</text>\n\n  <rect x="30" y="166" width="315" height="62" rx="6" fill="#eff6ff" stroke="#93c5fd" stroke-width="1.2"/>\n  <text x="38" y="183" font-size="10" fill="#1e3a8a">• 1 ve 2. deney: [X] sabit, [Y] 2 katına çıkınca r 2 katına çıktı ⇒ Y¹</text>\n  <text x="38" y="200" font-size="10" fill="#1e3a8a">• 1 ve 3. deney: [Y] sabit, [X] 3 katına çıkınca r 9 (3²) katına çıktı ⇒ X²</text>\n  <text x="38" y="218" font-size="10.5" font-weight="bold" fill="#1d4ed8">• Hız Bağıntısı: r = k · [X]² · [Y]   (Toplam Derece n = 3)</text>\n\n  <rect x="370" y="44" width="310" height="194" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="525" y="66" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">Hız Sabiti (k) Hesabı ve Özellikleri</text>\n  <rect x="384" y="76" width="282" height="52" rx="6" fill="#ffffff" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="525" y="95" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#78350f">1. Deneyde Yerine Koyma:</text>\n  <text x="525" y="114" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#b45309">2·10⁻³ = k · (0,1)² · (0,1)  ⇒  k = 2 L² / (mol²·s)</text>\n\n  <text x="384" y="148" font-size="10.5" font-weight="bold" fill="#15803d">✓ k Değerini Değiştiren Faktörler (TSK):</text>\n  <text x="392" y="164" font-size="10" fill="#334155">1. Sıcaklık (T) artışı k\'yi artırır.</text>\n  <text x="392" y="180" font-size="10" fill="#334155">2. Katalizör (K) ve Temas Yüzeyi (S) k\'yi değiştirir.</text>\n  <text x="384" y="202" font-size="10.5" font-weight="bold" fill="#dc2626">✗ k Değerini Değiştirmeyen Faktör:</text>\n  <text x="392" y="218" font-size="10" fill="#334155">Reaktiflerin derişimi [X], [Y] k\'yi değiştirmez!</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
